class Node(object):
  def __init__(self, data):
    self.data = data
    self.left = None
    self.right = None


class BST(object):
  def __init__(self, root):
    self.root = Node(root)

def insert(self, new_val):
  self.insert_helper(self.root, new_val)

def insert_helper(self, current, new_val):
  if current.data < new_val:  # 当前结点值 小于 插入值
    if current.right:               # 如果存在右子树，则在右子树中插入
      self.insert_helper(current.right, new_val)
    else:
      current.right = Node(new_val) # 如果不存在右子树，则直接作为右子结点
  else:                       # 当前结点值 大于等于 插入值
      if current.left:              # 如果存在左子树，则在左子树中插入
        self.insert_helper(current.left, new_val)
      else:
        current.left = Node(new_val) # 如果不存在左子树，则直接作为左子结点

def search(self, find_val):
  return self.search_helper(self.root, find_val)

def search_helper(self, current, find_val):
  if current:
    if current.data == find_val:   # 如果当前结点值与查找值相等，则找到返回True
        return True
    elif current.data < find_val:  # 如果当前结点值小于查找值 
        return self.search_helper(current.right, find_val) # 则在右子树中查找
    else:                          # 如果当前结点值大于查找值
        return self.search_helper(current.left, find_val)  # 则在左子树中查找

class Node(object):
  def __init__(self, data):
    self.data = data
    self.left = None
    self.right = None


class BST(object):
  def __init__(self, root):
    self.root = Node(root)

  def insert(self, new_val):
    self.insert_helper(self.root, new_val)

  def insert_helper(self, current, new_val):
    if current.data < new_val:
      if current.right:
        self.insert_helper(current.right, new_val)
      else:
        current.right = Node(new_val)
    else:
        if current.left:
          self.insert_helper(current.left, new_val)
        else:
          current.left = Node(new_val)

  def search(self, find_val):
    return self.search_helper(self.root, find_val)

  def search_helper(self, current, find_val):
    if current:
      if current.data == find_val:
          return True
      elif current.data < find_val:
          return self.search_helper(current.right, find_val)
      else:
          return self.search_helper(current.left, find_val)

